  Activity(
      slug: 'lezing-het-palmhoutwrak',
      title: 'Lezing het Palmhoutwrak',
      start: DateTime(2026, 10, 20, 19, 30),
      end: DateTime(2026, 10, 20, 21, 30),
      kind: ActivityKind.lezing,
      venueName: 'Bibliotheek Beverwijk',
      venueAddress: 'Kerkplein 5 Beverwijk, 1941 HD Netherlands',
      organizer: 'Bibliotheek Beverwijk', price: 'Leden € 5,00 · niet-leden € 7,50',
      image: 'https://www.historischekringheemskerk.nl/wp-content/uploads/2026/10/VOC-vloot.jpg',
      registration: ActivityRegistration(externalUrl: 'https://obijmond.op-shop.nl/1368/ontdek-het-palmhoutwrak/20-10-2026', externalLabel: 'Aanmelden via Bibliotheek IJmond'),
      published: '2026-10-08T15:09:33+00:00',
      blocks: [
        ParagraphBlock('Het Palmhoutwrak is een uitzonderlijk goed bewaard 17e-eeuws scheepswrak op de bodem van de Waddenzee. Thijs Coenen van de Rijksdienst voor het Cultureel Erfgoed en zijn collega’s hebben vele duiksessies naar het wrak ondernomen. Thijs komt tijdens de Maand van de Geschiedenis over zijn bevindingen vertellen tijdens deze boeiende lezing.'),
        ParagraphBlock('Het Palmhoutwrak'),
        ParagraphBlock('Eeuwenlang lag dit bijzondere schip verborgen voor de kust van Texel, begraven onder een dikke laag zand in de ondiepe Waddenzee. Hierdoor bleven voorwerpen zo uitzonderlijk goed bewaard dat de tijd werd stilgezet. In 2009 werd bij toeval het schip ontdekt dat, vanwege de grote lading stammetjes, bekend werd als het ‘Palmhoutwrak’.'),
        ParagraphBlock('Bewaard onder het zand'),
        ParagraphBlock('In het gebied waar ooit de Reede van Texel lag, aan de oostzijde van het eiland, zijn vooral in de 17e en 18e eeuw honderden schepen vergaan. Van de meeste schepen is niets bewaard gebleven, maar sommige raakten kort na de schipbreuk bedekt met slib en sediment waardoor deze wrakken als tijdscapsules in de zeebodem bewaard bleven.'),
        ParagraphBlock('Mysterie ontrafeld'),
        ParagraphBlock('Sinds de ontdekking van het wrak proberen experts en specialisten van over de hele wereld de vondsten als puzzelstukjes in een groter verhaal te passen. Wat was het voor schip? Hoe was het leven aan boord? Wat zegt de schat aan luxe over de bemanning of de route die het schip aflegde? Met behulp van moderne technieken wordt steeds een stukje van het mysterie ontrafeld. Thijs zal tijdens de lezing uitgebreid op deze zaken ingaan.'),
        ParagraphBlock('De jurk van Texel'),
        ParagraphBlock('In het Palmhoutwrak is een indrukwekkende zijden jurk gevonden. Het kostbare kledingstuk is, ondanks een verblijf van bijna vier eeuwen op de zeebodem, nog in een verrassend goede staat. Het is een wereldwijd unieke vondst; er is nauwelijks kleding uit de zeventiende eeuw bewaard gebleven. De jurk is eén van de topstukken in de collectie van Museum Kaap Skil in Oudeschild op Texel.'),
        ParagraphBlock('Huis van Hilde'),
        ParagraphBlock('Over het Palmhoutwrak is tot juni 2027 de boeiende tentoonstelling ‘Schip vol raadsels’ te zien. Ook zijn er verdiepende lezingen over de tentoonstelling Schip vol Raadsels.'),
        ParagraphBlock('Voor aanmeldingen ga naar https://obijmond.op-shop.nl/1368/ontdek-het-palmhoutwrak/20-10-2026', links: [ContentLink('https://obijmond.op-shop.nl/1368/ontdek-het-palmhoutwrak/20-10-2026', 'https://obijmond.op-shop.nl/1368/ontdek-het-palmhoutwrak/20-10-2026')]),
        ParagraphBlock('Daar kun je je aanmelden als lid voor € 5,00 en niet lid € 7,50'),
      ],
    ),
  Activity(
      slug: 'lezing-over-cornelis-corneliszoon',
      title: 'Lezing over Cornelis Corneliszoon',
      start: DateTime(2026, 10, 27, 19, 30),
      end: DateTime(2026, 10, 27, 21, 30),
      kind: ActivityKind.lezing,
      venueName: 'Historisch Huis HKH',
      venueAddress: 'A.Verherentstraat 5 Heemskerk',
      organizer: 'WG Lezingen',
      image: 'https://www.historischekringheemskerk.nl/wp-content/uploads/2026/09/cornelis.jpg',
      registration: ActivityRegistration(capacity: 25, registered: 21),
      published: '2026-09-21T16:52:53+00:00',
      blocks: [
        ParagraphBlock('Wie heeft ooit gehoord van Cornelis Corneliszoon van Uitgeest? In geschiedenisboeken komt zijn naam nauwelijks voor. Zelfs zijn geboorte- en sterfdatum staan niet vast. Hij was getrouwd met Trijn Pieters, de dochter van de molenaar en noemde zichzelf een ‘schamel huysman met wijff ende kijnderen belast’.'),
        ParagraphBlock('Toch deed deze eenvoudige boer, timmerman en molenmaker in 1593 een van de belangrijkste uitvindingen uit de vaderlandse geschiedenis: de houtzaagmolen. Door het toepassen van een krukas werd het mogelijk de draaiende beweging van de wieken om te zetten in het op en neer bewegen van zagen. Dit machinaal op de wind zagen van balken en planken ging dertig keer sneller dan met de hand, wat tot dan toe gebruikelijk was.'),
        ParagraphBlock('De houtzaagmolen kwam op een goed moment. Spaanse troepen hadden hier gedurende de Tachtigjarige Oorlog al plunderend en brandstichtend een spoor van vernielingen achtergelaten. Er was dan ook een enorme vraag naar gezaagd hout. Voor herstel en herbouw van woningen, molens, boerderijen en pakhuizen. Maar ook en vooral voor scheepsbouw, om zo over zee handel te kunnen drijven.'),
        ParagraphBlock('Toch heeft Cornelis Corneliszoon van Uitgeest nooit de waardering en erkenning gekregen die hij verdient. Hij was een miskend genie. Alle reden dus om hier als eerbetoon aandacht te vragen voor deze bijzondere Uitgeester.'),
        ParagraphBlock('De Stichting Cornelis Corneliszoon in Uitgeest geeft op verschillende manieren aandacht aan deze zoon van Uitgeest. Arie Zonjee van de Stichting komt hierover vertellen bij de Historische Kring Heemskerk'),
        ParagraphBlock('Opgeven bij opgeven@historischekringheemskerk.nl max. 25 mensen.', links: [ContentLink('opgeven@historischekringheemskerk.nl', 'mailto:opgeven@historischekringheemskerk.nl')]),
        ParagraphBlock('Uw opgave is pas definitief als u een bevestiging heeft gekregen. Geen bevestiging gehad, neem dan opnieuw mailcontact op met het opgeef mailadres.'),
      ],
    ),
